-- CT-STRUCTURE additive contract v1; base entities/occupancies remain owned by foundation.
CREATE TABLE structure_templates(organization_id uuid NOT NULL REFERENCES organizations(id),id uuid NOT NULL,name text NOT NULL,flags jsonb NOT NULL,version int NOT NULL DEFAULT 1,PRIMARY KEY(organization_id,id));
CREATE TABLE structure_role_settings(organization_id uuid NOT NULL,role_id uuid NOT NULL,template_id uuid,flags jsonb NOT NULL,version int NOT NULL DEFAULT 1,PRIMARY KEY(organization_id,role_id),FOREIGN KEY(organization_id,role_id) REFERENCES entities(organization_id,id),FOREIGN KEY(organization_id,template_id) REFERENCES structure_templates(organization_id,id));
CREATE TABLE structure_mandates(organization_id uuid NOT NULL,id uuid NOT NULL,role_id uuid NOT NULL,member_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN ('DIRECT','INTERIM','ELECTED')),scope text NOT NULL DEFAULT '',starts_at timestamptz NOT NULL,ends_at timestamptz,ended_at timestamptz,proposal_id uuid,proposal_revision int,version int NOT NULL DEFAULT 1,PRIMARY KEY(organization_id,id),FOREIGN KEY(organization_id,role_id) REFERENCES entities(organization_id,id),FOREIGN KEY(organization_id,member_id) REFERENCES members(organization_id,id),CHECK(ends_at IS NULL OR ends_at>starts_at),CHECK(kind='DIRECT' OR ends_at IS NOT NULL),CHECK(kind<>'ELECTED' OR (proposal_id IS NOT NULL AND proposal_revision>0)),UNIQUE(organization_id,proposal_id,proposal_revision));
CREATE TABLE structure_aliases(organization_id uuid NOT NULL,id uuid NOT NULL,source_role_id uuid NOT NULL,circle_id uuid NOT NULL,label text NOT NULL,version int NOT NULL DEFAULT 1,PRIMARY KEY(organization_id,id),FOREIGN KEY(organization_id,source_role_id) REFERENCES entities(organization_id,id),FOREIGN KEY(organization_id,circle_id) REFERENCES entities(organization_id,id),UNIQUE(organization_id,source_role_id,circle_id));
CREATE TABLE structure_fields(organization_id uuid NOT NULL,id uuid NOT NULL,key text NOT NULL,label text NOT NULL,target text NOT NULL CHECK(target IN ('CIRCLE','ROLE','BOTH')),schema jsonb NOT NULL,governed boolean NOT NULL DEFAULT false,version int NOT NULL DEFAULT 1,PRIMARY KEY(organization_id,id),UNIQUE(organization_id,key),CHECK(NOT(governed AND schema->>'type'='COMPUTED')));
CREATE TABLE structure_field_revisions(organization_id uuid NOT NULL,field_id uuid NOT NULL,version int NOT NULL,definition jsonb NOT NULL,at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(organization_id,field_id,version),FOREIGN KEY(organization_id,field_id) REFERENCES structure_fields(organization_id,id));
CREATE TABLE structure_values(organization_id uuid NOT NULL,entity_id uuid NOT NULL,field_id uuid NOT NULL,value jsonb NOT NULL,schema_version int NOT NULL,version int NOT NULL DEFAULT 1,PRIMARY KEY(organization_id,entity_id,field_id),FOREIGN KEY(organization_id,entity_id) REFERENCES entities(organization_id,id),FOREIGN KEY(organization_id,field_id,schema_version) REFERENCES structure_field_revisions(organization_id,field_id,version));
CREATE TABLE structure_indicators(organization_id uuid NOT NULL,id uuid NOT NULL,entity_id uuid NOT NULL,name text NOT NULL,kind text NOT NULL CHECK(kind IN ('METRIC','CHECKLIST')),value_type text NOT NULL CHECK(value_type IN ('NUMBER','BOOLEAN','TEXT')),unit text NOT NULL,required_units jsonb NOT NULL,version int NOT NULL DEFAULT 1,PRIMARY KEY(organization_id,id),FOREIGN KEY(organization_id,entity_id) REFERENCES entities(organization_id,id),CHECK(kind<>'CHECKLIST' OR value_type='BOOLEAN'));
CREATE TABLE structure_records(organization_id uuid NOT NULL,id uuid NOT NULL,indicator_id uuid NOT NULL,period text NOT NULL,unit_key text NOT NULL,value jsonb NOT NULL,recorded_by uuid NOT NULL,version int NOT NULL,at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(organization_id,id),FOREIGN KEY(organization_id,indicator_id) REFERENCES structure_indicators(organization_id,id),FOREIGN KEY(organization_id,recorded_by) REFERENCES members(organization_id,id),UNIQUE(organization_id,indicator_id,period,unit_key,version));
CREATE TABLE structure_views(organization_id uuid NOT NULL,id uuid NOT NULL,member_id uuid NOT NULL,name text NOT NULL,config jsonb NOT NULL,version int NOT NULL DEFAULT 1,PRIMARY KEY(organization_id,id),FOREIGN KEY(organization_id,member_id) REFERENCES members(organization_id,id));
CREATE TABLE structure_history(organization_id uuid NOT NULL,id uuid NOT NULL,resource_id uuid NOT NULL,action text NOT NULL,before_value jsonb,after_value jsonb,actor_id uuid NOT NULL,at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(organization_id,id),FOREIGN KEY(organization_id,actor_id) REFERENCES members(organization_id,id));
CREATE TABLE structure_snapshots(organization_id uuid NOT NULL,id uuid NOT NULL,name text NOT NULL,structure_revision int NOT NULL,graph jsonb NOT NULL,at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(organization_id,id));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['structure_templates','structure_role_settings','structure_mandates','structure_aliases','structure_fields','structure_field_revisions','structure_values','structure_indicators','structure_records','structure_views','structure_history','structure_snapshots'] LOOP
EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);
EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);
EXECUTE format($policy$CREATE POLICY tenant ON %I USING (organization_id = nullif(current_setting('orgmap.organization_id',true),'')::uuid) WITH CHECK (organization_id = nullif(current_setting('orgmap.organization_id',true),'')::uuid)$policy$,t);
EXECUTE format('GRANT SELECT,INSERT,UPDATE ON %I TO orgmap_app',t);
END LOOP; END $$;
